-- Users are managed exclusively by Supabase Auth (auth.users).
-- No public users table or project membership table is needed.
create table public.projects (
  id uuid primary key default gen_random_uuid(),
  title text not null check (char_length(btrim(title)) between 1 and 120),
  description text not null default '' check (char_length(description) <= 2000),
  owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade
);

create table public.project_stages (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  position integer not null default 0 check (position >= 0),
  constraint project_stages_project_id_id_key unique (project_id, id)
);

create table public.tasks (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  stage_id uuid not null,
  title text not null check (char_length(btrim(title)) between 1 and 180),
  description text not null default '' check (char_length(description) <= 40000),
  position integer not null default 0 check (position >= 0),
  done boolean not null default false,
  constraint tasks_project_stage_fkey foreign key (project_id, stage_id)
    references public.project_stages(project_id, id) on delete cascade
);

-- Index ownership lookups, foreign keys, and ordered board queries.
create index projects_owner_id_idx on public.projects (owner_id);
create index project_stages_project_position_idx on public.project_stages (project_id, position, id);
create index tasks_project_stage_position_idx on public.tasks (project_id, stage_id, position, id);

alter table public.projects enable row level security;
alter table public.project_stages enable row level security;
alter table public.tasks enable row level security;

revoke all on table public.projects, public.project_stages, public.tasks
  from public, anon, authenticated;
grant select, insert, update, delete on table public.projects, public.project_stages, public.tasks
  to authenticated;

create policy projects_select_own on public.projects for select to authenticated
  using (owner_id = (select auth.uid()));
create policy projects_insert_own on public.projects for insert to authenticated
  with check (owner_id = (select auth.uid()));
create policy projects_update_own on public.projects for update to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));
create policy projects_delete_own on public.projects for delete to authenticated
  using (owner_id = (select auth.uid()));

create policy project_stages_select_own on public.project_stages for select to authenticated
  using (exists (select 1 from public.projects p
    where p.id = project_stages.project_id and p.owner_id = (select auth.uid())));
create policy project_stages_insert_own on public.project_stages for insert to authenticated
  with check (exists (select 1 from public.projects p
    where p.id = project_stages.project_id and p.owner_id = (select auth.uid())));
create policy project_stages_update_own on public.project_stages for update to authenticated
  using (exists (select 1 from public.projects p
    where p.id = project_stages.project_id and p.owner_id = (select auth.uid())))
  with check (exists (select 1 from public.projects p
    where p.id = project_stages.project_id and p.owner_id = (select auth.uid())));
create policy project_stages_delete_own on public.project_stages for delete to authenticated
  using (exists (select 1 from public.projects p
    where p.id = project_stages.project_id and p.owner_id = (select auth.uid())));

create policy tasks_select_own on public.tasks for select to authenticated
  using (exists (select 1 from public.projects p
    where p.id = tasks.project_id and p.owner_id = (select auth.uid())));
create policy tasks_insert_own on public.tasks for insert to authenticated
  with check (exists (select 1 from public.projects p
    where p.id = tasks.project_id and p.owner_id = (select auth.uid())));
create policy tasks_update_own on public.tasks for update to authenticated
  using (exists (select 1 from public.projects p
    where p.id = tasks.project_id and p.owner_id = (select auth.uid())))
  with check (exists (select 1 from public.projects p
    where p.id = tasks.project_id and p.owner_id = (select auth.uid())));
create policy tasks_delete_own on public.tasks for delete to authenticated
  using (exists (select 1 from public.projects p
    where p.id = tasks.project_id and p.owner_id = (select auth.uid())));

comment on table public.projects is 'Projects privately owned by a Supabase Auth user.';
comment on table public.project_stages is 'Ordered task board columns belonging to a project.';
comment on table public.tasks is 'Ordered project tasks. The composite foreign key enforces stage/project consistency.';
comment on column public.tasks.done is 'Explicit completion flag; the application updates this when moving tasks to/from a completed stage.';

-- This function is an internal DDL event trigger, not an application RPC.
-- Keep automatic RLS enforcement but remove direct API execution privileges.
revoke execute on function public.rls_auto_enable() from public, anon, authenticated;

-- Application operations run as the caller. RLS remains the authorization boundary.
create function public.create_project_with_stages(p_title text, p_description text default '')
returns uuid language plpgsql security invoker set search_path = '' as $$
declare project_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'Sign in to continue.' using errcode = '42501'; end if;
  insert into public.projects(title,description) values (btrim(p_title),coalesce(p_description,''))
    returning id into project_id;
  insert into public.project_stages(project_id,name,position) values
    (project_id,'Not Started',0),(project_id,'In Progress',1),(project_id,'Done',2);
  return project_id;
end;
$$;

create function public.move_project_task(p_task_id uuid, p_stage_id uuid, p_before_id uuid default null)
returns void language plpgsql security invoker set search_path = '' as $$
declare
  task_project uuid;
  old_stage uuid;
  target_name text;
  ordered_ids uuid[];
  before_position integer;
  item uuid;
  current_position integer := 0;
begin
  if (select auth.uid()) is null then raise exception 'Sign in to continue.' using errcode = '42501'; end if;
  select project_id,stage_id into task_project,old_stage from public.tasks where id=p_task_id;
  if not found then raise exception 'Task not found or access denied.' using errcode = '42501'; end if;
  -- Serialize moves within a project so positions are updated as one transaction.
  perform 1 from public.projects where id=task_project for update;
  if not found then raise exception 'Project access denied.' using errcode = '42501'; end if;
  select name into target_name from public.project_stages where id=p_stage_id and project_id=task_project;
  if not found then raise exception 'Stage does not belong to this project.' using errcode = '22023'; end if;
  if p_task_id=p_before_id then return; end if;
  select coalesce(array_agg(id order by position,id),array[]::uuid[]) into ordered_ids
    from public.tasks where project_id=task_project and stage_id=p_stage_id and id<>p_task_id;
  if p_before_id is null then
    ordered_ids := array_append(ordered_ids,p_task_id);
  else
    before_position := array_position(ordered_ids,p_before_id);
    if before_position is null then raise exception 'Target task is not in this stage.' using errcode = '22023'; end if;
    ordered_ids := coalesce(ordered_ids[1:before_position-1],array[]::uuid[])
      || array[p_task_id] || coalesce(ordered_ids[before_position:cardinality(ordered_ids)],array[]::uuid[]);
  end if;
  update public.tasks set stage_id=p_stage_id,done=(target_name='Done') where id=p_task_id and project_id=task_project;
  foreach item in array ordered_ids loop
    update public.tasks set position=current_position where id=item and project_id=task_project;
    current_position := current_position+1;
  end loop;
  if old_stage<>p_stage_id then
    current_position := 0;
    for item in select id from public.tasks where project_id=task_project and stage_id=old_stage order by position,id loop
      update public.tasks set position=current_position where id=item;
      current_position := current_position+1;
    end loop;
  end if;
end;
$$;
revoke all on function public.create_project_with_stages(text,text) from public,anon;
revoke all on function public.move_project_task(uuid,uuid,uuid) from public,anon;
grant execute on function public.create_project_with_stages(text,text) to authenticated;
grant execute on function public.move_project_task(uuid,uuid,uuid) to authenticated;

-- Private task files, stored at user/project/task/unique-filename.
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types)
values ('task-attachments','task-attachments',false,10485760,
array['image/png','image/jpeg','image/gif','image/webp','application/pdf','text/plain','text/csv','text/markdown','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.oasis.opendocument.text']);

create policy "Task owners upload attachments" on storage.objects for insert to authenticated
with check (
 bucket_id='task-attachments'
 and (storage.foldername(name))[1]=(select auth.uid())::text
 and array_length(storage.foldername(name),1)=3
 and exists(select 1 from public.tasks t join public.projects p on p.id=t.project_id
 where t.id::text=(storage.foldername(name))[3]
 and p.id::text=(storage.foldername(name))[2] and p.owner_id=(select auth.uid()))
);
create policy "Task owners read attachments" on storage.objects for select to authenticated
using (
 bucket_id='task-attachments'
 and (storage.foldername(name))[1]=(select auth.uid())::text
 and exists(select 1 from public.tasks t join public.projects p on p.id=t.project_id
 where t.id::text=(storage.foldername(name))[3]
 and p.id::text=(storage.foldername(name))[2] and p.owner_id=(select auth.uid()))
);
create policy "Task owners remove attachments" on storage.objects for delete to authenticated
using (
 bucket_id='task-attachments'
 and (storage.foldername(name))[1]=(select auth.uid())::text
 and exists(select 1 from public.tasks t join public.projects p on p.id=t.project_id
 where t.id::text=(storage.foldername(name))[3]
 and p.id::text=(storage.foldername(name))[2] and p.owner_id=(select auth.uid()))
);
